import fs from 'fs';
import path from 'path';
import terser from 'terser';
import defaultConfig from './rollup.config';

// Синхронный вызов минимизации (убедитесь, что файлы build/*.js уже созданы пред. шагом)
const minificationOptions = {}; // можно оставить пустым или настроить options

const moduleJsPath = path.join(__dirname, 'build/myThree.module.js');
if (fs.existsSync(moduleJsPath)) {
    const code = fs.readFileSync(moduleJsPath, "utf8");
    // В terser.minify функции могут возвращать Promise, но для обычного кода работает синхронный результат
    terser.minify(code).then(result => {
        if (result.error) console.error(result.error);
        else fs.writeFileSync("build/myThree.module.min.js", result.code, "utf8");
    });
}

const jsPath = path.join(__dirname, 'build/myThree.js');
if (fs.existsSync(jsPath)) {
    const code = fs.readFileSync(jsPath, "utf8");
    terser.minify(code).then(result => {
        if (result.error) console.error(result.error);
        else fs.writeFileSync("build/myThree.min.js", result.code, "utf8");
    });
}

const banner = fs.readFileSync(path.join(__dirname, 'licenseBanner.txt'));

export default Object.assign({}, defaultConfig, {
    output: [{
        exports: 'named',
        file: './build/myThree.js',
        format: 'umd',
        name: 'MyThree',
        banner: banner
    }
    ],
});